const INCOME_DIVISOR = 5e8; // tunes how much Hash Power (HP) converts to AETHER/sec

/* =========================================================
   TOKENOMICS — AETHER mining supply cap with Bitcoin-style
   halving. Only passive mining income (Claim / Auto-Claim /
   Offline Earnings) counts against this; Missions, Events,
   Guild, Loot Box, and Marketplace payouts are unaffected.
   ========================================================= */

const AETHER_MAX_SUPPLY = 100_000_000;

// how many halvings have occurred by the time `totalMined` AETHER has been mined
function miningHalvingEpoch(totalMined) {
  if (totalMined >= AETHER_MAX_SUPPLY - 1) return 64; // effectively exhausted, rate ~0
  const fractionRemaining = 1 - totalMined / AETHER_MAX_SUPPLY;
  return Math.max(0, Math.floor(-Math.log2(fractionRemaining)));
}

// mining rate multiplier for the current epoch: 1, 0.5, 0.25, 0.125, ... never quite reaches 0
function miningHalvingMultiplier(totalMined) {
  return Math.pow(0.5, miningHalvingEpoch(totalMined));
}

