/* --- Per-item LEVEL system (no longer tier/swap gear) ---
   Each item above is bought once in the SHOP, then leveled up individually
   in the UPGRADE menu up to MAX_LEVEL. HP & cost scale up each level. */
const MAX_LEVEL = 50;
const LEVEL_HP_GROWTH = 1.06; // +6% hashrate per level
const LEVEL_COST_GROWTH = 1.12; // +12% cost per level
const LEVEL_COST_BASE_RATIO = 0.08; // initial level-up cost = base * this ratio

function itemHpAtLevel(item, level) {
  if (level <= 0) return 0;
  return item.hp * Math.pow(LEVEL_HP_GROWTH, level - 1);
}
function itemLevelUpCost(item, level) {
  const base = Math.max(item.buyCost, 500) * LEVEL_COST_BASE_RATIO;
  return Math.ceil(base * Math.pow(LEVEL_COST_GROWTH, level - 1));
}
function findPartItem(itemId) {
  for (const cat of PART_CATEGORIES) {
    const item = cat.items.find((i) => i.id === itemId);
    if (item) return { item, category: cat };
  }
  return null;
}

