function guildMilestoneFor(n) {
  return Math.round(3000 * Math.pow(1.6, n));
}
function guildRewardFor(n) {
  return Math.round(2000 * Math.pow(1.5, n));
}

/* =========================================================
   LOOT BOX — spend AETHER for a random reward: a small/big
   AETHER payout, Materials, or a free unowned Part.
   ========================================================= */

const LOOTBOX_COST = 500;

const LOOTBOX_REWARDS = [
  { weight: 35, type: "aether", label: "AETHER", min: 200, max: 800 },
  { weight: 20, type: "aether", label: "AETHER", min: 1000, max: 3000 },
  { weight: 20, type: "material", pool: ["Metal Ingot", "Metal Plate", "Storage Unit", "Fuel Barrel"], min: 3, max: 8 },
  { weight: 12, type: "material", pool: ["Nano Alloy", "Core Crystal", "Carbon Fiber"], min: 1, max: 3 },
  { weight: 5, type: "material", pool: ["Quantum Alloy"], min: 1, max: 2 },
  { weight: 3, type: "aether", label: "JACKPOT AETHER", min: 8000, max: 15000 },
  { weight: 5, type: "part" },
];

function rollLootbox(ownedItems) {
  const totalWeight = LOOTBOX_REWARDS.reduce((s, r) => s + r.weight, 0);
  let roll = Math.random() * totalWeight;
  let chosen = LOOTBOX_REWARDS[0];
  for (const r of LOOTBOX_REWARDS) {
    if (roll < r.weight) {
      chosen = r;
      break;
    }
    roll -= r.weight;
  }

  if (chosen.type === "aether") {
    const amount = Math.round((chosen.min + Math.random() * (chosen.max - chosen.min)) / 10) * 10;
    return { type: "aether", amount, label: chosen.label };
  }
  if (chosen.type === "material") {
    const name = chosen.pool[Math.floor(Math.random() * chosen.pool.length)];
    const qty = Math.round(chosen.min + Math.random() * (chosen.max - chosen.min));
    const poolItem = TRADE_ITEM_POOL.find((p) => p.name === name);
    return { type: "material", name, qty, icon: poolItem?.icon, iconColor: poolItem?.iconColor };
  }
  // type === "part": pick a random currently-unowned part
  const unowned = [];
  PART_CATEGORIES.forEach((cat) => cat.items.forEach((item) => {
    if (!(ownedItems[item.id] > 0)) unowned.push({ item, cat });
  }));
  if (unowned.length === 0) {
    return { type: "aether", amount: 2000, label: "AETHER (bonus)" };
  }
  const pick = unowned[Math.floor(Math.random() * unowned.length)];
  return { type: "part", item: pick.item, category: pick.cat };
}

function randomListingPrice(basePrice) {
  const factor = 0.85 + Math.random() * 0.4; // 0.85x - 1.25x
  return Math.max(10, Math.round((basePrice * factor) / 10) * 10);
}

function makeBotListing() {
  const poolItem = TRADE_ITEM_POOL[Math.floor(Math.random() * TRADE_ITEM_POOL.length)];
  const seller = BOT_SELLER_NAMES[Math.floor(Math.random() * BOT_SELLER_NAMES.length)];
  return {
    id: `bot-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    seller,
    name: poolItem.name,
    icon: poolItem.icon,
    iconColor: poolItem.iconColor,
    type: poolItem.type,
    price: randomListingPrice(poolItem.basePrice),
  };
}

function makeBotListings(count) {
  return Array.from({ length: count }, () => makeBotListing());
}

function bumpInventoryTag(tag) {
  const n = parseInt(String(tag).replace(/[^0-9]/g, ""), 10);
  if (Number.isNaN(n)) return "x1";
  return `x${n + 1}`;
}

function parseInventoryQty(tag) {
  const n = parseInt(String(tag).replace(/[^0-9]/g, ""), 10);
  return Number.isNaN(n) ? 0 : n;
}

function getInventoryQty(inventory, name) {
  const found = inventory.find((it) => it.name === name && it.type !== "rig");
  return found ? parseInventoryQty(found.tag) : 0;
}

